package org.brightstats.desktop;

import java.util.*;
import javafx.scene.canvas.*;
import javafx.scene.paint.*;
import javafx.scene.effect.DropShadow;
import javafx.scene.text.*;
import org.brightstats.data.UserPreferences;
import org.brightstats.report.XmlText;
import com.google.gson.*;

/** Shared curved-link/rounded-card geometry for live canvas and genuine vector export. */
final class ModelDiagramGraphics {
    record Node(String name,int indicators,String mode,double x,double y,boolean selected){Node{if(name==null||mode==null||indicators<0||!Double.isFinite(x)||!Double.isFinite(y)||Math.abs(x)>20000||Math.abs(y)>20000)throw new IllegalArgumentException("Invalid model graphic identity or coordinates.");}}
    record Edge(int source,int target,Double estimate){}
    record Palette(String background,String grid,String card,String text,String muted,String border,String accent,boolean contrast){}
    record Curve(double sx,double sy,double cx,double cy,double tx,double ty){}
    record Badge(double x,double y,double curveX,double curveY,double width){}
    private ModelDiagramGraphics(){}
    static Palette palette(UserPreferences.Theme theme,UserPreferences.Accent accent){String color=switch(accent){case OCEAN->"#36b7df";case VIOLET->"#b399ff";case FOREST->"#65d0a2";case AMBER->"#ffd078";};if(theme==UserPreferences.Theme.HIGH_CONTRAST)return new Palette("#000000","#454545","#000000","#ffffff","#ffffff","#ffffff","#ffff00",true);if(theme==UserPreferences.Theme.DARK)return new Palette("#101c2a","#293d52","#20354a","#edf6ff","#b3c7d9","#7e9db7",color,false);return new Palette("#f2f6fb","#d2dfeb","#ffffff","#18364e","#506b82","#607f98",switch(accent){case OCEAN->"#087ea3";case VIOLET->"#7550bf";case FOREST->"#197b55";case AMBER->"#9a6000";},false);}
    static boolean hit(double x,double y,double centerX,double centerY){double dx=Math.abs(x-centerX),dy=Math.abs(y-centerY);if(dx>76||dy>48)return false;if(dx<=56||dy<=28)return true;return Math.pow(dx-56,2)+Math.pow(dy-28,2)<=400;}
    static Curve curve(Node a,Node b){double dx=b.x()-a.x(),dy=b.y()-a.y(),length=Math.hypot(dx,dy);if(length<1e-8)return null;double ux=dx/length,uy=dy/length,ra=radius(ux,uy),rb=radius(-ux,-uy),sx=a.x()+ux*ra,sy=a.y()+uy*ra,tx=b.x()-ux*rb,ty=b.y()-uy*rb,bend=Math.min(40,length*.09);return new Curve(sx,sy,(sx+tx)/2-uy*bend,(sy+ty)/2+ux*bend,tx,ty);}
    private static double radius(double ux,double uy){double low=0,high=100;for(int j=0;j<40;j++){double middle=(low+high)/2;if(hit(ux*middle,uy*middle,0,0))low=middle;else high=middle;}return low;}
    private record Box(double x,double y,double width,double height){}
    private static final class CollisionIndex {
        final Map<Long,List<Box>> cells=new HashMap<>();
        void add(Box box){for(int x=cell(box.x());x<=cell(box.x()+box.width());x++)for(int y=cell(box.y());y<=cell(box.y()+box.height());y++)cells.computeIfAbsent(key(x,y),k->new ArrayList<>()).add(box);}
        double overlap(double ax,double ay,double width,double height){Set<Box> nearby=new LinkedHashSet<>();for(int x=cell(ax);x<=cell(ax+width);x++)for(int y=cell(ay);y<=cell(ay+height);y++)nearby.addAll(cells.getOrDefault(key(x,y),List.of()));double total=0;for(var box:nearby)total+=ModelDiagramGraphics.overlap(ax,ay,width,height,box.x(),box.y(),box.width(),box.height());return total;}
        static int cell(double value){return (int)Math.floor(value/128);}static long key(int x,int y){return ((long)x<<32)^(y&0xffffffffL);}
    }
    static Map<Integer,Badge> badges(List<Node> nodes,List<Edge> edges,double width,double height){Map<Integer,Badge> placed=new LinkedHashMap<>();CollisionIndex obstacles=new CollisionIndex(),labels=new CollisionIndex();for(var node:nodes)obstacles.add(new Box(node.x()-81,node.y()-53,162,106));for(int i=0;i<edges.size();i++){var edge=edges.get(i);if(edge.estimate()==null||!Double.isFinite(edge.estimate())||edge.source()<0||edge.target()<0||edge.source()>=nodes.size()||edge.target()>=nodes.size())continue;var c=curve(nodes.get(edge.source()),nodes.get(edge.target()));if(c==null)continue;Text measure=new Text(estimateText(edge.estimate()));measure.setFont(Font.font("System",FontWeight.BOLD,12));double badgeWidth=Math.max(60,Math.min(100,measure.getLayoutBounds().getWidth()+16)),bestScore=Double.POSITIVE_INFINITY;Badge best=null;for(double t:new double[]{.5,.4,.6,.3,.7,.2,.8})for(double offset:new double[]{0,20,-20,40,-40,60,-60}){double bx=(1-t)*(1-t)*c.sx()+2*(1-t)*t*c.cx()+t*t*c.tx(),by=(1-t)*(1-t)*c.sy()+2*(1-t)*t*c.cy()+t*t*c.ty(),dx=2*(1-t)*(c.cx()-c.sx())+2*t*(c.tx()-c.cx()),dy=2*(1-t)*(c.cy()-c.sy())+2*t*(c.ty()-c.cy()),length=Math.max(1,Math.hypot(dx,dy)),x=Math.max(badgeWidth/2+3,Math.min(width-badgeWidth/2-3,bx-dy/length*offset)),y=Math.max(18,Math.min(height-18,by+dx/length*offset));double score=Math.abs(t-.5)*100+Math.abs(offset);score+=obstacles.overlap(x-badgeWidth/2,y-15,badgeWidth,24)*1000;score+=labels.overlap(x-badgeWidth/2-3,y-18,badgeWidth+6,30)*1000;if(score<bestScore){bestScore=score;best=new Badge(x,y,bx,by,badgeWidth);}}if(best!=null){placed.put(i,best);labels.add(new Box(best.x()-best.width()/2,best.y()-15,best.width(),24));}}return Map.copyOf(placed);}
    private static double overlap(double ax,double ay,double aw,double ah,double bx,double by,double bw,double bh){return Math.max(0,Math.min(ax+aw,bx+bw)-Math.max(ax,bx))*Math.max(0,Math.min(ay+ah,by+bh)-Math.max(ay,by));}
    private static String estimateText(double value){return String.format(Locale.ROOT,value!=0&&(Math.abs(value)<.0005||Math.abs(value)>=10000)?"%.2e":"%.3f",value);}
    static void draw(Canvas canvas,List<Node> nodes,List<Edge> edges,Palette palette,boolean grid){var gc=canvas.getGraphicsContext2D();gc.setEffect(null);gc.setFill(Color.web(palette.background()));gc.fillRect(0,0,canvas.getWidth(),canvas.getHeight());var labels=badges(nodes,edges,canvas.getWidth(),canvas.getHeight());if(grid){gc.setFill(Color.web(palette.grid()));for(int x=20;x<canvas.getWidth();x+=24)for(int y=20;y<canvas.getHeight();y+=24)gc.fillOval(x,y,1.7,1.7);}for(int edgeIndex=0;edgeIndex<edges.size();edgeIndex++){var edge=edges.get(edgeIndex);if(edge.source()<0||edge.target()<0||edge.source()>=nodes.size()||edge.target()>=nodes.size())continue;var curve=curve(nodes.get(edge.source()),nodes.get(edge.target()));if(curve==null)continue;String color=edge.estimate()!=null&&Double.isFinite(edge.estimate())?palette.accent():palette.border();gc.setStroke(Color.web(color));gc.setFill(Color.web(color));gc.setLineWidth(edge.estimate()==null?1.8:2.5);gc.setLineDashes(edge.estimate()!=null&&edge.estimate()<0?new double[]{6,4}:new double[0]);gc.beginPath();gc.moveTo(curve.sx(),curve.sy());gc.quadraticCurveTo(curve.cx(),curve.cy(),curve.tx(),curve.ty());gc.stroke();gc.setLineDashes();double angle=Math.atan2(curve.ty()-curve.cy(),curve.tx()-curve.cx()),ux=Math.cos(angle),uy=Math.sin(angle);gc.fillPolygon(new double[]{curve.tx(),curve.tx()-ux*12+uy*5,curve.tx()-ux*12-uy*5},new double[]{curve.ty(),curve.ty()-uy*12-ux*5,curve.ty()-uy*12+ux*5},3);if(edge.estimate()!=null&&Double.isFinite(edge.estimate())){var badge=labels.get(edgeIndex);double x=badge.x(),y=badge.y();if(Math.hypot(x-badge.curveX(),y-badge.curveY())>12){gc.setStroke(Color.web(palette.border()));gc.setLineWidth(.7);gc.strokeLine(badge.curveX(),badge.curveY(),x,y);}gc.setFill(Color.web(palette.card()));gc.fillRoundRect(x-badge.width()/2,y-15,badge.width(),24,10,10);gc.setFill(Color.web(palette.text()));gc.setFont(Font.font("System",FontWeight.BOLD,12));gc.setTextAlign(TextAlignment.CENTER);gc.fillText(estimateText(edge.estimate()),x,y+1);}}
        gc.setTextAlign(TextAlignment.CENTER);for(var node:nodes){Color card=Color.web(palette.card()),accent=Color.web(palette.accent());Color fill=node.selected()?card.interpolate(accent,palette.contrast()?.15:.16):card;if(!palette.contrast())gc.setEffect(new DropShadow(12,0,3,Color.web("#000000",.15)));gc.setFill(new LinearGradient(0,0,0,1,true,CycleMethod.NO_CYCLE,new Stop(0,fill.interpolate(Color.WHITE,palette.background().equals("#101c2a")?.035:0)),new Stop(1,fill)));gc.fillRoundRect(node.x()-76,node.y()-48,152,96,40,40);gc.setEffect(null);gc.setStroke(node.selected()?accent:Color.web(palette.border()));gc.setLineWidth(node.selected()?3:1.4);gc.strokeRoundRect(node.x()-76,node.y()-48,152,96,40,40);gc.setFill(accent);gc.fillRoundRect(node.x()-40,node.y()-43,80,3,3,3);gc.setFill(Color.web(palette.text()));gc.setFont(Font.font("System",FontWeight.SEMI_BOLD,15));var lines=lines(node.name());if(lines.size()==1)gc.fillText(lines.getFirst(),node.x(),node.y()-4,132);else{gc.fillText(lines.getFirst(),node.x(),node.y()-13,132);gc.fillText(lines.getLast(),node.x(),node.y()+5,132);}gc.setFont(Font.font("System",11));gc.setFill(Color.web(palette.muted()));gc.fillText(node.indicators()+" indicators · Mode "+node.mode(),node.x(),node.y()+29,136);}if(nodes.isEmpty()){gc.setFill(Color.web(palette.muted()));gc.setFont(Font.font("System",18));gc.setTextAlign(TextAlignment.LEFT);gc.fillText("Import data, then add constructs to start your model.",65,100);}gc.setTextAlign(TextAlignment.LEFT);
    }
    static String svg(double width,double height,List<Node> nodes,List<Edge> edges,Palette palette,boolean grid,JsonObject source,String title){JsonObject metadata=new JsonObject();metadata.addProperty("format","bright-stats-model-graphic");metadata.addProperty("version",1);metadata.add("graph",source.deepCopy());metadata.add("renderedEdges",new GsonBuilder().serializeNulls().create().toJsonTree(edges));metadata.add("palette",new Gson().toJsonTree(palette));metadata.addProperty("showGrid",grid);var labels=badges(nodes,edges,width,height);StringBuilder out=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"").append(width).append("\" height=\"").append(height).append("\" viewBox=\"0 0 ").append(width).append(' ').append(height).append("\" role=\"img\" aria-label=\"").append(esc(title)).append("\"><title>").append(esc(title)).append("</title><metadata>").append(esc(metadata.toString())).append("</metadata><defs><pattern id=\"model-grid\" width=\"24\" height=\"24\" patternUnits=\"userSpaceOnUse\"><circle cx=\"20\" cy=\"20\" r=\"0.85\" fill=\"").append(palette.grid()).append("\"/></pattern><marker id=\"model-arrow\" markerWidth=\"8\" markerHeight=\"8\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0 0 L0 6 L7 3 Z\" fill=\"context-stroke\"/></marker></defs><rect width=\"100%\" height=\"100%\" fill=\"").append(palette.background()).append("\"/>");if(grid)out.append("<rect width=\"100%\" height=\"100%\" fill=\"url(#model-grid)\"/>");out.append("<g font-family=\"system-ui,sans-serif\">");for(int edgeIndex=0;edgeIndex<edges.size();edgeIndex++){var edge=edges.get(edgeIndex);if(edge.source()<0||edge.target()<0||edge.source()>=nodes.size()||edge.target()>=nodes.size())continue;var c=curve(nodes.get(edge.source()),nodes.get(edge.target()));if(c==null)continue;String color=edge.estimate()!=null?palette.accent():palette.border();out.append("<path d=\"M ").append(c.sx()).append(' ').append(c.sy()).append(" Q ").append(c.cx()).append(' ').append(c.cy()).append(' ').append(c.tx()).append(' ').append(c.ty()).append("\" fill=\"none\" stroke=\"").append(color).append("\" stroke-width=\"2\"");if(edge.estimate()!=null&&edge.estimate()<0)out.append(" stroke-dasharray=\"6 4\"");out.append("/>");double angle=Math.atan2(c.ty()-c.cy(),c.tx()-c.cx()),ux=Math.cos(angle),uy=Math.sin(angle);out.append("<polygon points=\"").append(c.tx()).append(",").append(c.ty()).append(" ").append(c.tx()-ux*12+uy*5).append(",").append(c.ty()-uy*12-ux*5).append(" ").append(c.tx()-ux*12-uy*5).append(",").append(c.ty()-uy*12+ux*5).append("\" fill=\"").append(color).append("\"/>");if(edge.estimate()!=null&&Double.isFinite(edge.estimate())){var badge=labels.get(edgeIndex);double x=badge.x(),y=badge.y();if(Math.hypot(x-badge.curveX(),y-badge.curveY())>12)out.append("<line x1=\"").append(badge.curveX()).append("\" y1=\"").append(badge.curveY()).append("\" x2=\"").append(x).append("\" y2=\"").append(y).append("\" stroke=\"").append(palette.border()).append("\" stroke-width=\"0.7\"/>");out.append("<rect x=\"").append(x-badge.width()/2).append("\" y=\"").append(y-15).append("\" width=\"").append(badge.width()).append("\" height=\"24\" rx=\"5\" fill=\"").append(palette.card()).append("\"/>");text(out,x,y+1,estimateText(edge.estimate()),palette.text(),12);}}for(var node:nodes){out.append("<g><title>").append(esc(node.name())).append("</title><rect x=\"").append(node.x()-76).append("\" y=\"").append(node.y()-48).append("\" width=\"152\" height=\"96\" rx=\"20\" fill=\"").append(cardColor(node,palette)).append("\" stroke=\"").append(node.selected()?palette.accent():palette.border()).append("\" stroke-width=\"").append(node.selected()?3:1.4).append("\"/><rect x=\"").append(node.x()-40).append("\" y=\"").append(node.y()-43).append("\" width=\"80\" height=\"3\" rx=\"1.5\" fill=\"").append(palette.accent()).append("\"/>");var lines=lines(node.name());if(lines.size()==1)text(out,node.x(),node.y()-4,lines.getFirst(),palette.text(),15);else{ text(out,node.x(),node.y()-13,lines.getFirst(),palette.text(),15);text(out,node.x(),node.y()+5,lines.getLast(),palette.text(),15);}text(out,node.x(),node.y()+29,node.indicators()+" indicators · Mode "+node.mode(),palette.muted(),11);out.append("</g>");}return out.append("</g></svg>").toString();}
    private static List<String> lines(String name){int[] codepoints=name.codePoints().toArray();if(codepoints.length<=17)return List.of(name);int split=17;for(int i=16;i>7;i--)if(Character.isWhitespace(codepoints[i])){split=i;break;}String first=new String(codepoints,0,split).strip(),rest=new String(codepoints,split,codepoints.length-split).strip();int[] tail=rest.codePoints().toArray();return List.of(first,tail.length>17?new String(tail,0,16)+"…":rest);}
    private static String cardColor(Node node,Palette palette){Color color=Color.web(palette.card());if(node.selected())color=color.interpolate(Color.web(palette.accent()),palette.contrast()?.15:.16);return String.format(Locale.ROOT,"#%02x%02x%02x",Math.round(color.getRed()*255),Math.round(color.getGreen()*255),Math.round(color.getBlue()*255));}
    private static void text(StringBuilder out,double x,double y,String value,String color,int size){Text measure=new Text(value);measure.setFont(Font.font("System",size));double maximum=size==15?132:size==11?136:58;out.append("<text x=\"").append(x).append("\" y=\"").append(y).append("\" fill=\"").append(color).append("\" font-size=\"").append(size).append("\" text-anchor=\"middle\"");if(measure.getLayoutBounds().getWidth()>maximum)out.append(" textLength=\"").append(maximum).append("\" lengthAdjust=\"spacingAndGlyphs\"");out.append(">").append(esc(value)).append("</text>");}
    private static String esc(String value){return XmlText.escape(value);}
}
